type:
∀ {p m : ℕ} {A : Type u_1} [inst : Fintype A] (label : A → ZMod p) {sizes : Fin m → ℕ}
  (s : GRWTSK.BalancedPartitionSampling.Sample sizes),
  ∑ a ∈ GRWTSK.BalancedPartitionSampling.output s, label a = ∑ i, label ((↑s).2 i)

∀ {p m : ℕ} {A : Type u_1} [inst : Fintype A] (label : A ↪ ZMod p) {sizes : Fin m → ℕ}
  (P : GRWTSK.BalancedPartitionSampling.Partition sizes) (i : Fin m),
  (GRWTSK.ZModBalancedPartition.partValues label P i).card = sizes i

∀ {p m : ℕ} {A : Type u_1} [inst : Fintype A] (label : A ↪ ZMod p) {sizes : Fin m → ℕ}
  (P : GRWTSK.BalancedPartitionSampling.Partition sizes) (i : Fin m),
  GRWTSK.ZModBalancedPartition.partValues label P i = Finset.map label {a | ↑P a = i}

∀ {p : ℕ} [inst : NeZero p] (B : Finset (ZMod p)) (δ : ℝ),
  GRWTSK.ZModSmallEnergySets.smallEnergyPoints B δ =
    {x | ∑ χ ∈ B, GRWTSK.ZModCharacterEnergy.modularDistance (χ * x) ^ 2 < δ * ↑B.card}

∀ {p : ℕ} [inst : NeZero p] (χ center : ZMod p) (r : ℝ),
  GRWTSK.ZModConcentratedFrequencies.phaseInterval χ center r =
    {x | GRWTSK.ZModCharacterEnergy.modularDistance (χ * x - center) ≤ r}
